/* Monster-only typed passives. Snapshot once; derive bonuses without mutating base stats. */
(function(g){'use strict';const L=g.DecideLegacyMonsterPassives||(typeof require==='function'?require('./legacy-monster-passives.js'):null),ids=['thick-hide','predators-instinct','undying-resilience','swarm-tactics','arcane-ward','ancient-might'].map(id=>'preset-skill-monster-'+id),fields=['monsterAttackBonusPercent','monsterDefenseBonus','monsterDamageReductionBonus','monsterMagicDefenseBonus','monsterAccuracyBonus','monsterEvasionBonus'];
const need=(v,msg)=>{if(!v)throw Error(msg);},empty=()=>({attackPercent:0,defense:0,physicalReduction:0,magicReduction:0,accuracy:0,evasion:0});
function compile(r){if(!r||r.kind!=='skill'||!ids.includes(r.id)||r.enabled===false||r.activePassive!=='Passive')return null;const values={};for(const field of fields){const n=r[field]===undefined||r[field]===null?0:r[field];if(!Number.isFinite(n)||Math.abs(n)>1000)return null;values[field]=n;}return {id:r.id,name:String(r.displayName||r.name).slice(0,160),values};}
function validate(v){need(v&&v.v===1&&Array.isArray(v.entries)&&v.entries.length<=6,'ข้อมูล Passive มอนสเตอร์ไม่ถูกต้อง');const seen=new Set();for(const e of v.entries){need(e&&ids.includes(e.id)&&!seen.has(e.id)&&typeof e.name==='string'&&e.name.length<=160&&e.values&&Object.keys(e.values).length===fields.length&&fields.every(k=>Number.isFinite(e.values[k])&&Math.abs(e.values[k])<=1000),'ค่า Passive มอนสเตอร์ไม่ถูกต้อง');seen.add(e.id);}return v;}
function bonuses(u){if(u.side!=='enemy'||!u.monsterPassives)return empty();const entries=u.monsterPassives.entries,view=L.withMonsterEffectiveStats({attack:100,defense:0,damageReduction:0,magicDefense:0,accuracy:0,evasion:0,skills:entries.map(e=>e.id)},{skill:entries.map(e=>({name:e.id,...e.values,enabled:true}))});return {attackPercent:view.__monsterAttackBonusPercent||0,defense:view.defense,physicalReduction:view.damageReduction,magicReduction:Math.max(0,view.magicDefense),accuracy:view.accuracy,evasion:view.evasion};}
function prepare(e,rows){if(e.design!==1||!e.tactical)return;for(const u of e.units.filter(u=>u.side==='enemy'&&u.monsterPassives===undefined)){const m=rows.find(r=>r.kind==='monster'&&r.id===u.monsterId&&r.enabled!==false);if(!m)continue;const entries=[];for(const ref of (Array.isArray(m.skills)?m.skills:[]).slice(0,100)){if(typeof ref!=='string')continue;const exact=rows.find(r=>r.kind==='skill'&&r.id===ref),matches=rows.filter(r=>r.kind==='skill'&&r.name===ref),r=exact||(matches.length===1?matches[0]:null),p=compile(r);if(p&&!entries.some(e=>e.id===p.id))entries.push(p);}u.monsterPassives={v:1,entries};validate(u.monsterPassives);}}
function describe(entry,unit){const rate=unit?.catalogStats?.v===1?1:5;const b=bonuses({side:'enemy',monsterPassives:{v:1,entries:[entry]}}),parts=[];if(b.attackPercent)parts.push('ดาเมจ '+(b.attackPercent>0?'+':'')+b.attackPercent+'%');if(b.defense)parts.push('หลบกายภาพ '+(b.defense>0?'+':'')+(b.defense*5)+' จุดเปอร์เซ็นต์');if(b.physicalReduction)parts.push('ลดดาเมจกายภาพ '+b.physicalReduction);if(b.magicReduction)parts.push('ลดดาเมจเวท '+b.magicReduction);if(b.accuracy)parts.push('แม่นยำ '+(b.accuracy>0?'+':'')+(b.accuracy*rate)+' จุดเปอร์เซ็นต์');if(b.evasion)parts.push('หลบทุกประเภท '+(b.evasion>0?'+':'')+(b.evasion*rate)+' จุดเปอร์เซ็นต์');return entry.name+' — '+(parts.join(' / ')||'ไม่มีโบนัสตัวเลข');}
function support(r,details=true){if(!ids.includes(r.id))return null;if(r.enabled===false)return 'Passive มอนสเตอร์ปิดใช้งาน';const p=compile(r);return p?(details?'Passive มอนสเตอร์ทำงาน • '+describe(p,{catalogStats:{v:1}}):'Passive มอนสเตอร์ทำงาน • ศึกษาเพื่อดูรายละเอียด'):'Passive มอนสเตอร์นี้ยังไม่รองรับค่าที่กำหนด';}
const api={compile,validate,prepare,bonuses,describe,support};g.DecideMonsterPassives=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
